const application =
  $('Select Sender Application')
    .first()?.json ?? {};

const downloadedItem =
  $input.first() ?? {};

const binary =
  downloadedItem.binary ?? {};

const resumeBinary =
  binary.resume;

function cleanText(value) {
  return String(value ?? '').trim();
}

function upper(value) {
  return cleanText(value).toUpperCase();
}

const blockingReasons = [];

const applicationStatus =
  upper(application.application_status);

const outreachMode =
  upper(application.outreach_mode);

const duplicateCampaign =
  application.duplicate_campaign === true ||
  upper(
    application.duplicate_campaign
  ) === 'TRUE';

const outreachApproval =
  upper(application.outreach_approval);

const outreachStatus =
  upper(application.outreach_status);

const draftFinalStatus =
  upper(application.draft_final_status);

const contactEmail =
  cleanText(application.contact_email);

const emailConfidence =
  upper(
    application.contact_email_confidence ??
    application.email_confidence
  );

const emailSubject =
  cleanText(
    application.email_subject ||
    application['email_subject ']
  );

const emailBody =
  cleanText(application.email_draft);

const sentAt =
  cleanText(application.sent_at);

const resumeFileId =
  cleanText(application.resume_file_id);

const resumeFilename =
  cleanText(application.resume_filename);

/*
Application and approval checks
*/
const eligibleForOutreach =
  applicationStatus === 'APPLIED' ||
  outreachMode === 'ADJACENT_ROLE' ||
  outreachMode === 'SPECULATIVE';

if (duplicateCampaign) {
  blockingReasons.push(
    'This opportunity is covered by an existing ' +
    'company outreach campaign.'
  );

  const coveredByKey =
    cleanText(
      application
        .covered_by_opportunity_key
    );

  const coveredByStatus =
    upper(
      application.covered_by_status
    );

  if (coveredByKey) {
    blockingReasons.push(
      `Canonical campaign: ${coveredByKey}.`
    );
  }

  if (coveredByStatus) {
    blockingReasons.push(
      `Canonical campaign status: ${coveredByStatus}.`
    );
  }
}

if (!eligibleForOutreach) {
  blockingReasons.push(
    'Outreach requires an APPLIED application or an ' +
    'explicit ADJACENT_ROLE or SPECULATIVE strategy.'
  );
}

if (outreachApproval !== 'APPROVED') {
  blockingReasons.push(
    `Outreach approval is ${outreachApproval || 'EMPTY'}; expected APPROVED.`
  );
}

if (outreachStatus !== 'DRAFT_READY') {
  blockingReasons.push(
    `Outreach status is ${outreachStatus || 'EMPTY'}; expected DRAFT_READY.`
  );
}

if (draftFinalStatus !== 'READY') {
  blockingReasons.push(
    `Draft final status is ${draftFinalStatus || 'EMPTY'}; expected READY.`
  );
}

/*
Recipient and message checks
*/
if (
  !contactEmail ||
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactEmail)
) {
  blockingReasons.push(
    'A valid contact email is required.'
  );
}

if (
  ![
    'HIGH',
    'MEDIUM',
    'USER_VERIFIED',
  ].includes(emailConfidence)
) {
  blockingReasons.push(
    `Email confidence is ${emailConfidence || 'EMPTY'}; ` +
    'expected HIGH, MEDIUM, or USER_VERIFIED.'
  );
}

if (!emailSubject) {
  blockingReasons.push(
    'Email subject is empty.'
  );
}

if (!emailBody) {
  blockingReasons.push(
    'Email draft is empty.'
  );
}

/*
Duplicate-send protection
*/
if (sentAt) {
  blockingReasons.push(
    `This outreach was already sent at ${sentAt}.`
  );
}

/*
Resume checks
*/
if (!resumeFileId) {
  blockingReasons.push(
    'Resume Google Drive file ID is missing.'
  );
}

if (!resumeFilename) {
  blockingReasons.push(
    'Resume filename is missing.'
  );
}

if (!resumeBinary) {
  blockingReasons.push(
    'The resume binary field "resume" is missing.'
  );
} else {
  const mimeType =
    cleanText(resumeBinary.mimeType);

  const fileName =
    cleanText(resumeBinary.fileName);

  if (mimeType !== 'application/pdf') {
    blockingReasons.push(
      `Resume MIME type is ${mimeType || 'EMPTY'}; expected application/pdf.`
    );
  }

  if (!fileName.toLowerCase().endsWith('.pdf')) {
    blockingReasons.push(
      'The downloaded resume filename does not end in .pdf.'
    );
  }
}

const sendGateStatus =
  blockingReasons.length === 0
    ? 'AUTHORIZED'
    : 'BLOCKED';

return [
  {
    json: {
      ...application,

      email_subject:
        emailSubject,

      contact_email:
        contactEmail,

      contact_email_confidence:
        emailConfidence,

      send_gate_status:
        sendGateStatus,

      send_gate_blocking_reasons:
        blockingReasons,

      application_status:
        applicationStatus,

      outreach_mode:
        outreachMode,

      duplicate_campaign:
        duplicateCampaign,

      send_gate_checked_at:
        new Date().toISOString(),
    },

    /*
    Preserve the downloaded PDF for the Gmail node.
    */
    binary,
  },
];

const incoming =
  $input.first()?.json ?? {};

const clean = value =>
  String(value ?? '').trim();

const opportunityKey =
  clean(
    incoming.opportunity_key ??
    incoming.body?.opportunity_key
  );

return [
  {
    json: {
      requested_opportunity_key:
        opportunityKey,

      sender_trigger_source:
        opportunityKey
          ? 'DASHBOARD'
          : 'MANUAL',

      sender_request_received_at:
        new Date().toISOString(),
    },
  },
];

const request =
  $('Normalize Sender Request')
    .first()
    .json ?? {};

const clean = value =>
  String(value ?? '').trim();

const upper = value =>
  clean(value).toUpperCase();

const requestedKey =
  clean(
    request.requested_opportunity_key
  );

const rows = $input
  .all()
  .map(item => item.json ?? {})
  .filter(
    row =>
      clean(row.opportunity_key)
  );


function blocked(
  message,
  reasons = [],
  extra = {},
) {
  return [
    {
      json: {
        sender_selection_ready: false,
        success: false,
        send_status: 'BLOCKED',

        message,

        opportunity_key:
          requestedKey,

        requested_opportunity_key:
          requestedKey,

        send_gate_blocking_reasons:
          reasons,

        sender_selection_checked_at:
          new Date().toISOString(),

        ...extra,
      },
    },
  ];
}


function normalizeDomain(value) {
  let domain =
    clean(value).toLowerCase();

  if (!domain) {
    return '';
  }

  return domain
    .replace(/^https?:\/\//, '')
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .replace(/^www\./, '')
    .replace(/\.$/, '');
}


function normalizeEmail(value) {
  return clean(value).toLowerCase();
}


function normalizeLinkedIn(value) {
  return clean(value)
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(/\/+$/, '');
}


function normalizeCompanyName(value) {
  return clean(value)
    .toLowerCase()
    .replace(/\s+/g, ' ');
}


function sharesCampaignIdentity(
  first,
  second,
) {
  const firstDomain =
    normalizeDomain(
      first.company_domain
    );

  const secondDomain =
    normalizeDomain(
      second.company_domain
    );

  if (
    firstDomain &&
    secondDomain &&
    firstDomain === secondDomain
  ) {
    return true;
  }


  const firstEmail =
    normalizeEmail(
      first.contact_email
    );

  const secondEmail =
    normalizeEmail(
      second.contact_email
    );

  if (
    firstEmail &&
    secondEmail &&
    firstEmail === secondEmail
  ) {
    return true;
  }


  const firstLinkedIn =
    normalizeLinkedIn(
      first.contact_linkedin_url
    );

  const secondLinkedIn =
    normalizeLinkedIn(
      second.contact_linkedin_url
    );

  if (
    firstLinkedIn &&
    secondLinkedIn &&
    firstLinkedIn === secondLinkedIn
  ) {
    return true;
  }


  /*
   * Company name is only a fallback when
   * neither row has a usable domain.
   */
  if (
    !firstDomain &&
    !secondDomain
  ) {
    const firstCompany =
      normalizeCompanyName(
        first.company_name
      );

    const secondCompany =
      normalizeCompanyName(
        second.company_name
      );

    if (
      firstCompany &&
      secondCompany &&
      firstCompany === secondCompany
    ) {
      return true;
    }
  }

  return false;
}


function campaignRank(candidate) {
  const outreachStatus =
    upper(candidate.outreach_status);

  const researchStatus =
    upper(
      candidate.contact_research_status
    );

  const approvalStatus =
    upper(
      candidate.outreach_approval
    );

  const sentAt =
    clean(candidate.sent_at);


  if (
    sentAt ||
    [
      'SENT',
      'REPLIED',
      'FOLLOW_UP_DUE',
    ].includes(outreachStatus)
  ) {
    return 500;
  }


  if (
    approvalStatus === 'APPROVED' ||
    outreachStatus === 'APPROVED'
  ) {
    return 400;
  }


  if (
    outreachStatus === 'DRAFT_READY'
  ) {
    return 300;
  }


  if (
    researchStatus === 'COMPLETED'
  ) {
    return 200;
  }


  if (
    researchStatus === 'IN_PROGRESS'
  ) {
    return 100;
  }


  return 0;
}


if (!requestedKey) {
  return blocked(
    'No opportunity_key was supplied to the sender.',
    [
      'A specific opportunity_key is required.',
    ],
    {
      duplicate_campaign: false,
    },
  );
}


const selected =
  rows.find(
    row =>
      clean(row.opportunity_key) ===
      requestedKey
  ) ?? null;


if (!selected) {
  return blocked(
    'The requested application was not found.',
    [
      'No matching Application_Tracker row was found.',
    ],
    {
      duplicate_campaign: false,
    },
  );
}


/*
 * Find every active campaign sharing the
 * selected row's company or contact identity.
 */
const relatedActiveCampaigns =
  rows
    .filter(candidate =>
      sharesCampaignIdentity(
        selected,
        candidate,
      ) &&
      campaignRank(candidate) > 0
    )
    .sort(
      (first, second) => {
        const rankDifference =
          campaignRank(second) -
          campaignRank(first);

        if (rankDifference) {
          return rankDifference;
        }

        const sentDifference =
          clean(second.sent_at)
            .localeCompare(
              clean(first.sent_at)
            );

        if (sentDifference) {
          return sentDifference;
        }

        return clean(
          first.opportunity_key
        ).localeCompare(
          clean(
            second.opportunity_key
          )
        );
      },
    );


const canonicalCampaign =
  relatedActiveCampaigns[0] ?? null;

const canonicalKey =
  clean(
    canonicalCampaign
      ?.opportunity_key
  );


if (
  canonicalCampaign &&
  canonicalKey &&
  canonicalKey !== requestedKey
) {
  const canonicalCompany =
    clean(
      canonicalCampaign.company_name
    ) ||
    clean(selected.company_name) ||
    'This company';

  const canonicalPosition =
    clean(
      canonicalCampaign.position_title
    ) ||
    'another opportunity';

  const canonicalContact =
    clean(
      canonicalCampaign.contact_name
    ) ||
    clean(
      canonicalCampaign.contact_email
    ) ||
    'the saved company contact';

  const canonicalStatus =
    upper(
      canonicalCampaign.outreach_status
    ) ||
    upper(
      canonicalCampaign
        .contact_research_status
    ) ||
    'ACTIVE';

  return blocked(
    `${canonicalCompany} already has an active company outreach campaign.`,
    [
      `Canonical campaign: ${canonicalPosition}.`,
      `Contact: ${canonicalContact}.`,
      `Campaign status: ${canonicalStatus}.`,
      'A second email cannot be sent for this company or contact.',
    ],
    {
      duplicate_campaign: true,

      covered_by_opportunity_key:
        canonicalKey,

      covered_by_company_name:
        canonicalCompany,

      covered_by_position_title:
        canonicalPosition,

      covered_by_contact:
        canonicalContact,

      covered_by_status:
        canonicalStatus,
    },
  );
}


return [
  {
    json: {
      ...selected,

      sender_selection_ready:
        true,

      success:
        true,

      duplicate_campaign:
        false,

      requested_opportunity_key:
        requestedKey,

      sender_selection_checked_at:
        new Date().toISOString(),
    },
  },
];

const blocked =
  $input.first()?.json ?? {};

return [
  {
    json: {
      ...blocked,
      success: false,
      send_status: 'BLOCKED',
    },
  },
];

const gate =
  $('Validate Email Send Gate')
    .first()
    .json ?? {};

return [
  {
    json: {
      ...gate,
      success: false,
      send_status: 'BLOCKED',

      message:
        'The outreach email was blocked by the sender safety gate.',
    },
  },
];

const gate =
  $('Validate Email Send Gate')
    .first()
    ?.json ?? {};

const gmail =
  $('Send Approved Outreach Email')
    .first()
    ?.json ?? {};

const clean = (value) =>
  String(value ?? '').trim();


function addBusinessDays(
  startDate,
  numberOfDays
) {
  const date =
    new Date(startDate);

  let addedDays = 0;

  while (
    addedDays < numberOfDays
  ) {
    date.setUTCDate(
      date.getUTCDate() + 1
    );

    const dayOfWeek =
      date.getUTCDay();

    const isWeekend =
      dayOfWeek === 0 ||
      dayOfWeek === 6;

    if (!isWeekend) {
      addedDays++;
    }
  }

  return date
    .toISOString()
    .slice(0, 10);
}


const sentAt =
  new Date().toISOString();

const followUpDate =
  addBusinessDays(
    sentAt,
    5
  );

const gmailMessageId =
  clean(
    gmail.id ||
    gmail.messageId
  );

const gmailThreadId =
  clean(
    gmail.threadId
  );


return [
  {
    json: {
      ...gate,

      opportunity_key:
        clean(gate.opportunity_key),

      contact_email:
        clean(gate.contact_email),

      outreach_status:
        'SENT',

      outreach_approval:
        'APPROVED',

      sent_at:
        sentAt,

      follow_up_date:
        followUpDate,

      response_status:
        'NO_RESPONSE',

      gmail_message_id:
        gmailMessageId,

      gmail_thread_id:
        gmailThreadId,

      last_updated:
        sentAt,
    },
  },
];
